// Applica le modifiche: alloggio nelle tappe + tipo_fonte vincolato a enum.
// Uso: salva nella cartella RADICE del progetto e lancia:  node applica-modifiche.js
import { writeFileSync, mkdirSync, readFileSync } from 'fs'
import { dirname } from 'path'

const files = {
  "functions/api/[[path]].js": '',
}

for (const [percorso, b64] of Object.entries(files)) {
  mkdirSync(dirname(percorso), { recursive: true })
  writeFileSync(percorso, Buffer.from(b64, 'base64'))
  console.log('scritto:', percorso)
}

const contenuto = readFileSync("functions/api/[[path]].js", 'utf8')
const ok = contenuto.includes('alloggio_nome') && contenuto.includes("'conferma_hotel'")
console.log(ok
  ? '\nVERIFICA OK — campi alloggio e enum tipo_fonte presenti.'
  : '\nATTENZIONE — le novità non ci sono: stai eseguendo una versione vecchia dello script.')
console.log('Ora: git add . && git commit -m "alloggio nelle tappe" && git push')